<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033}.wrap{max-width:1050px;margin:auto;padding:78px 12px 32px}h1{margin:0 0 4px}.sub{color:#64748b;font-size:13px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.card{background:#fff;border-radius:15px;padding:14px}.card.big{grid-column:1/-1}.k{font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em}.v{font-size:24px;font-weight:900;margin-top:4px}.s{font-size:12px;color:#64748b;margin-top:4px}.section{margin-top:18px}.section h2{font-size:18px;margin:0 0 10px}.row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #eef2f7}.row:last-child{border:0}.quick{display:grid;grid-template-columns:1fr 1fr;gap:8px}.quick a{text-decoration:none;background:#172033;color:#fff;border-radius:11px;padding:11px 12px;font-weight:800;font-size:13px;text-align:center}.empty{text-align:center;color:#64748b;padding:18px}@media(min-width:760px){.wrap{padding-top:35px}.grid{grid-template-columns:repeat(4,1fr)}.card.big{grid-column:span 2}.quick{grid-template-columns:repeat(4,1fr)}}</style></head><body><main class="wrap"><h1>Dashboard</h1><div class="sub">Resumen operativo de Hache Natación</div><div id="contenido"><div class="empty">Cargando…</div></div></main><script>const c=document.getElementById('contenido');const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0});async function cargar(){try{const r=await fetch('/api/dashboard.php'),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');c.innerHTML=`<div class="grid"><div class="card"><div class="k">Alumnos activos</div><div class="v">${d.alumnos_activos}</div></div><div class="card"><div class="k">Pendientes</div><div class="v">${d.pendientes}</div></div><div class="card"><div class="k">Mensualidades pagadas</div><div class="v">${d.mensualidades.cantidad}</div><div class="s">${money(d.mensualidades.total)}</div></div><div class="card"><div class="k">Ingresos del mes</div><div class="v">${money(d.caja.total)}</div><div class="s">${d.caja.cantidad} pagos</div></div><div class="card"><div class="k">Intensivos activos</div><div class="v">${d.intensivos}</div></div><div class="card"><div class="k">Avisos hoy</div><div class="v">${d.avisos_hoy}</div></div><div class="card"><div class="k">Reposiciones</div><div class="v">${d.reposiciones}</div><div class="s">disponibles</div></div><div class="card"><div class="k">Fecha</div><div class="v" style="font-size:18px">${d.fecha}</div></div></div><section class="section"><h2>Acciones rápidas</h2><div class="quick"><a href="/alumnos.php">Alumnos</a><a href="/pagos.php">Registrar pago</a><a href="/sesiones.php">Asistencia</a><a href="/ausencias.php">Ausencias</a></div></section><section class="section"><h2>Ocupación por horario</h2><div class="card">${d.horarios.length?d.horarios.map(x=>`<div class="row"><strong>${String(x.hora_inicio).slice(0,5)}–${String(x.hora_fin).slice(0,5)}</strong><span>${x.alumnos} alumno${x.alumnos==1?'':'s'}</span></div>`).join(''):'<div class="empty">Sin alumnos asignados.</div>'}</div></section>`}catch(e){c.innerHTML='<div class="empty">'+e.message+'</div>'}}cargar();</script></body></html>